1	"use client";
2	
3	import React, { useState, useEffect, useRef, useCallback } from "react";
4	import { motion, AnimatePresence } from "framer-motion";
5	import {
6	  QrCode,
7	  Copy,
8	  Check,
9	  CheckCircle2,
10	  Clock,
11	  RefreshCw,
12	  AlertCircle,
13	  Smartphone,
14	  ShieldCheck,
15	  Building2,
16	  ZoomIn,
17	  X,
18	  Sparkles,
19	  Zap,
20	} from "lucide-react";
21	import { AnimatedModal } from "@/components/ui/modal";
22	
23	export interface SettledDetails {
24	  amount: number;
25	  newBalance: number | null;
26	  paymentReference?: string | null;
27	  channel?: string | null;
28	}
29	
30	export interface P2PTopupSessionData {
31	  sessionId: string;
32	  sessionCode: string;
33	  channel: "GCASH" | "MARIBANK" | "MAYA" | string;
34	  baseAmount: number;
35	  centavosOffset: number;
36	  expectedAmount: number;
37	  expiresAt?: string;
38	  qrCodeUrl: string;
39	  receiverName: string;
40	  receiverNumber: string;
41	  bankName?: string;
42	}
43	
44	export interface P2PTopupModalProps {
45	  isOpen: boolean;
46	  onClose: () => void;
47	  sessionData: P2PTopupSessionData | null;
48	  onSuccess: () => void;
49	}
50	
51	// Pleasant harmonic chime synthesizer for instant settlement celebration
52	function playP2PChime() {
53	  if (typeof window === "undefined") return;
54	  try {
55	    const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
56	    if (!AudioCtx) return;
57	    const ctx = new AudioCtx();
58	    const now = ctx.currentTime;
59	
60	    const osc1 = ctx.createOscillator();
61	    const gain1 = ctx.createGain();
62	    osc1.type = "sine";
63	    osc1.frequency.setValueAtTime(587.33, now); // D5
64	    osc1.frequency.exponentialRampToValueAtTime(880, now + 0.12); // A5
65	    gain1.gain.setValueAtTime(0.18, now);
66	    gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
67	    osc1.connect(gain1);
68	    gain1.connect(ctx.destination);
69	    osc1.start(now);
70	    osc1.stop(now + 0.35);
71	
72	    const osc2 = ctx.createOscillator();
73	    const gain2 = ctx.createGain();
74	    osc2.type = "sine";
75	    osc2.frequency.setValueAtTime(1174.66, now + 0.14); // D6
76	    gain2.gain.setValueAtTime(0.2, now + 0.14);
77	    gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.7);
78	    osc2.connect(gain2);
79	    gain2.connect(ctx.destination);
80	    osc2.start(now + 0.14);
81	    osc2.stop(now + 0.7);
82	  } catch {
83	    // Graceful fallback if audio is not unlocked
84	  }
85	}
86	
87	export function P2PTopupModal({
88	  isOpen,
89	  onClose,
90	  sessionData,
91	  onSuccess,
92	}: P2PTopupModalProps) {
93	  const [timeLeft, setTimeLeft] = useState<number>(15 * 60);
94	  const [copiedAmount, setCopiedAmount] = useState<boolean>(false);
95	  const [copiedAccount, setCopiedAccount] = useState<boolean>(false);
96	  const [isConfirmed, setIsConfirmed] = useState<boolean>(false);
97	  const [isQrLightboxOpen, setIsQrLightboxOpen] = useState<boolean>(false);
98	  const [settledDetails, setSettledDetails] = useState<SettledDetails | null>(null);
99	  const [autoCloseSeconds, setAutoCloseSeconds] = useState<number>(5);
100	
101	  // Trigger confirmed settlement ceremony
102	  const handlePaymentSettled = useCallback(
103	    (details: SettledDetails) => {
104	      setSettledDetails(details);
105	      setIsConfirmed(true);
106	      playP2PChime();
107	      onSuccess();
108	    },
109	    [onSuccess]
110	  );
111	
112	  // 5-Second Auto-Close Countdown upon Confirmed Settlement
113	  useEffect(() => {
114	    if (!isConfirmed) return;
115	
116	    const timer = setInterval(() => {
117	      setAutoCloseSeconds((prev) => {
118	        if (prev <= 1) {
119	          clearInterval(timer);
120	          onClose();
121	          return 0;
122	        }
123	        return prev - 1;
124	      });
125	    }, 1000);
126	
127	    return () => clearInterval(timer);
128	  }, [isConfirmed, onClose]);
129	
130	  // Reset or initialize state when modal opens
131	  useEffect(() => {
132	    if (isOpen && sessionData) {
133	      setIsConfirmed(false);
134	      setSettledDetails(null);
135	      setAutoCloseSeconds(5);
136	      setCopiedAmount(false);
137	      setCopiedAccount(false);
138	      setIsQrLightboxOpen(false);
139	
140	      let initialRemaining = 15 * 60;
141	      if (sessionData.expiresAt) {
142	        const expTime = new Date(sessionData.expiresAt).getTime();
143	        if (!isNaN(expTime)) {
144	          initialRemaining = Math.max(0, Math.floor((expTime - Date.now()) / 1000));
145	        }
146	      }
147	      setTimeLeft(initialRemaining);
148	    }
149	  }, [isOpen, sessionData]);
150	
151	  // 15-Minute Countdown Timer
152	  useEffect(() => {
153	    if (!isOpen || !sessionData || isConfirmed || timeLeft <= 0) return;
154	
155	    const timer = setInterval(() => {
156	      setTimeLeft((prev) => {
157	        if (prev <= 1) {
158	          clearInterval(timer);
159	          return 0;
160	        }
161	        return prev - 1;
162	      });
163	    }, 1000);
164	
165	    return () => clearInterval(timer);
166	  }, [isOpen, sessionData, isConfirmed, timeLeft]);
167	
168	  // Live session polling every 3 seconds
169	  useEffect(() => {
170	    const lookupId = sessionData?.sessionId || sessionData?.sessionCode;
171	    if (!isOpen || !lookupId || isConfirmed || timeLeft <= 0) return;
172	
173	    let isMounted = true;
174	
175	    async function pollSession() {
176	      if (!isMounted || isConfirmed || !lookupId) return;
177	      try {
178	        const res = await fetch(
179	          `/api/payment/p2p/status/${encodeURIComponent(lookupId)}?_t=${Date.now()}`,
180	          { cache: "no-store" }
181	        );
182	        if (!res.ok) return;
183	        const data = await res.json();
184	        if (!isMounted || isConfirmed) return;
185	
186	        const isSettled =
187	          data?.status?.toUpperCase() === "COMPLETED" ||
188	          data?.status?.toUpperCase() === "SETTLED" ||
189	          Boolean(data?.isCompleted) ||
190	          Boolean(data?.isSettled) ||
191	          data?.session?.status?.toUpperCase() === "COMPLETED" ||
192	          data?.session?.status?.toUpperCase() === "SETTLED";
193	
194	        if (isSettled) {
195	          const settledAmount =
196	            data.amount !== undefined && data.amount !== null
197	              ? Number(data.amount)
198	              : data.session?.received_amount !== undefined && data.session?.received_amount !== null
199	              ? Number(data.session.received_amount)
200	              : Number(sessionData?.expectedAmount ?? 0);
201	
202	          const settledNewBalance =
203	            data.newBalance !== undefined && data.newBalance !== null
204	              ? Number(data.newBalance)
205	              : data.session?.newBalance !== undefined && data.session?.newBalance !== null
206	              ? Number(data.session.newBalance)
207	              : null;
208	
209	          const settledRef =
210	            data.paymentReference ||
211	            data.payment_reference ||
212	            data.session?.payment_reference ||
213	            null;
214	
215	          const settledChan =
216	            data.channel ||
217	            data.session?.channel ||
218	            sessionData?.channel ||
219	            "P2P";
220	
221	          handlePaymentSettled({
222	            amount: settledAmount,
223	            newBalance: settledNewBalance,
224	            paymentReference: settledRef,
225	            channel: settledChan,
226	          });
227	        }
228	      } catch {
229	        // Continue polling silently
230	      }
231	    }
232	
233	    const pollInterval = setInterval(pollSession, 3000);
234	    // Trigger initial poll immediately
235	    pollSession();
236	
237	    return () => {
238	      isMounted = false;
239	      clearInterval(pollInterval);
240	    };
241	  }, [
242	    isOpen,
243	    sessionData?.sessionId,
244	    sessionData?.sessionCode,
245	    sessionData?.expectedAmount,
246	    sessionData?.channel,
247	    isConfirmed,
248	    timeLeft,
249	    handlePaymentSettled,
250	  ]);
251	
252	  const copyText = (text: string, type: "amount" | "account") => {
253	    if (!text) return;
254	    navigator.clipboard.writeText(text);
255	    if (type === "amount") {
256	      setCopiedAmount(true);
257	      setTimeout(() => setCopiedAmount(false), 2000);
258	    } else {
259	      setCopiedAccount(true);
260	      setTimeout(() => setCopiedAccount(false), 2000);
261	    }
262	  };
263	
264	  const minutes = Math.floor(timeLeft / 60);
265	  const seconds = timeLeft % 60;
266	  const formattedCountdown = `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
267	
268	  const isMariBank = String(sessionData?.channel || "").toUpperCase().includes("MARI");
269	  const channelDisplay = isMariBank ? "MariBank" : "GCash";
270	  const creditedAmount =
271	    settledDetails?.amount !== undefined
272	      ? settledDetails.amount
273	      : sessionData
274	      ? Number(sessionData.expectedAmount)
275	      : 0;
276	  const settledNewBalance = settledDetails?.newBalance;
277	  const displayChannel =
278	    settledDetails?.channel || channelDisplay;
279	  const displayReference =
280	    settledDetails?.paymentReference || null;
281	
282	  return (
283	    <>
284	      <AnimatedModal
285	        isOpen={isOpen && !!sessionData}
286	        onClose={onClose}
287	        maxWidth="max-w-lg"
288	        className="border border-neutral-200 dark:border-white/10 shadow-2xl rounded-2xl bg-white dark:bg-[#14161D] text-neutral-900 dark:text-zinc-100 overflow-hidden"
289	      >
290	        <div className="p-6">
291	          <AnimatePresence mode="wait">
292	            {isConfirmed ? (
293	              <motion.div
294	                key="confirmed"
295	                initial={{ opacity: 0, scale: 0.95 }}
296	                animate={{ opacity: 1, scale: 1 }}
297	                exit={{ opacity: 0, scale: 0.95 }}
298	                transition={{ type: "spring", stiffness: 350, damping: 25 }}
299	                className="space-y-5"
300	              >
301	                {/* Double-Bezel Rounded Card */}
302	                <div className="rounded-2xl p-[1px] bg-gradient-to-b from-emerald-500/30 via-white/[0.08] to-white/[0.02] shadow-2xl shadow-emerald-950/20">
303	                  <div className="rounded-[15px] bg-neutral-50 dark:bg-[#14161D] border border-neutral-200 dark:border-white/10 p-6 space-y-6 relative overflow-hidden">
304	                    {/* Emerald Radial Background Glow */}
305	                    <div className="absolute -top-24 left-1/2 -translate-x-1/2 w-64 h-48 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none" />
306	
307	                    {/* Animated Emerald Glowing Badge with Checkmark */}
308	                    <div className="relative mx-auto w-16 h-16 flex items-center justify-center">
309	                      <div className="absolute inset-0 rounded-full bg-emerald-400/20 blur-xl animate-pulse" />
310	                      <div className="relative w-14 h-14 rounded-full bg-emerald-500/15 border border-emerald-400/30 ring-1 ring-emerald-400/20 flex items-center justify-center shadow-lg shadow-emerald-500/20">
311	                        <motion.div
312	                          initial={{ scale: 0.8, opacity: 0 }}
313	                          animate={{ scale: 1, opacity: 1 }}
314	                          transition={{ type: "spring", stiffness: 400, damping: 20, delay: 0.08 }}
315	                        >
316	                          <CheckCircle2 className="w-8 h-8 text-emerald-400" />
317	                        </motion.div>
318	                      </div>
319	                    </div>
320	
321	                    {/* Headline */}
322	                    <div className="text-center space-y-1">
323	                      <h3 className="text-xl font-bold text-white tracking-tight font-sans">
324	                        Top-Up Confirmed
325	                      </h3>
326	                      <p className="text-xs text-zinc-400 font-sans">
327	                        Funds verified &amp; instantly credited to your wholesale float
328	                      </p>
329	                    </div>
330	
331	                    {/* Monospace Currency Chip (JetBrains Mono): "+₱1.47 Credited" */}
332	                    <div className="flex justify-center">
333	                      <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-emerald-500/10 border border-emerald-500/25 text-emerald-300 font-mono tabular-nums text-sm font-bold shadow-sm">
334	                        <Sparkles className="w-4 h-4 text-emerald-400 shrink-0" />
335	                        <span>+₱{creditedAmount.toFixed(2)} Credited</span>
336	                      </div>
337	                    </div>
338	
339	                    {/* New Usable Balance Display: "Updated Float: ₱1,055.86" */}
340	                    <div className="p-4 rounded-xl bg-zinc-950/80 border border-white/[0.06] text-center space-y-1">
341	                      <div className="text-[11px] font-sans font-medium text-zinc-400 uppercase tracking-wider">
342	                        Usable Wholesale Float
343	                      </div>
344	                      <div className="text-2xl font-bold font-mono tabular-nums text-white tracking-tight">
345	                        {settledNewBalance !== null && settledNewBalance !== undefined
346	                          ? `Updated Float: ₱${settledNewBalance.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
347	                          : `Updated Float: ₱${creditedAmount.toFixed(2)}`}
348	                      </div>
349	                      <div className="text-[11px] font-mono text-emerald-400 flex items-center justify-center space-x-1">
350	                        <Check className="w-3.5 h-3.5" />
351	                        <span>Available for automated order fulfillment upon confirmation</span>
352	                      </div>
353	                    </div>
354	
355	                    {/* Transaction Reference & Bank Channel Indicator */}
356	                    <div className="space-y-2 pt-1 font-mono text-xs">
357	                      <div className="flex items-center justify-between p-2.5 rounded-lg bg-zinc-950/60 border border-white/[0.04]">
358	                        <span className="text-zinc-400 text-[11px]">Bank Channel:</span>
359	                        <div className="flex items-center space-x-1.5 text-zinc-200 font-semibold">
360	                          {displayChannel.toUpperCase().includes("MARI") ? (
361	                            <Building2 className="w-3.5 h-3.5 text-sky-400" />
362	                          ) : (
363	                            <Smartphone className="w-3.5 h-3.5 text-blue-400" />
364	                          )}
365	                          <span>{displayChannel}</span>
366	                        </div>
367	                      </div>
368	
369	                      <div className="flex items-center justify-between p-2.5 rounded-lg bg-zinc-950/60 border border-white/[0.04]">
370	                        <span className="text-zinc-400 text-[11px]">Session Code:</span>
371	                        <span className="text-zinc-200 font-semibold font-mono">{sessionData?.sessionCode}</span>
372	                      </div>
373	
374	                      {displayReference && (
375	                        <div className="flex items-center justify-between p-2.5 rounded-lg bg-zinc-950/60 border border-white/[0.04]">
376	                          <span className="text-zinc-400 text-[11px]">Bank Ref:</span>
377	                          <span className="text-emerald-400 font-mono text-[11px] truncate max-w-[200px]" title={displayReference}>
378	                            {displayReference}
379	                          </span>
380	                        </div>
381	                      )}
382	                    </div>
383	                  </div>
384	                </div>
385	
386	                {/* Primary Action Button: "Done / Back to Wallet" (with 5-second auto-close progress bar) */}
387	                <div className="pt-1">
388	                  <button
389	                    type="button"
390	                    onClick={onClose}
391	                    className="group relative w-full overflow-hidden py-3 px-4 rounded-xl bg-gradient-to-r from-emerald-600 to-emerald-500 hover:from-emerald-500 hover:to-emerald-400 text-white font-sans font-semibold text-xs uppercase tracking-wider transition-all shadow-lg shadow-emerald-950/40 active:scale-[0.98] duration-150"
392	                  >
393	                    <span className="relative z-10 flex items-center justify-center space-x-2">
394	                      <span>Done / Back to Wallet</span>
395	                      <span className="text-emerald-100/90 font-mono text-xs tabular-nums lowercase">
396	                        ({autoCloseSeconds}s)
397	                      </span>
398	                    </span>
399	                    {/* 5-second auto-close progress bar */}
400	                    <motion.div
401	                      initial={{ scaleX: 1 }}
402	                      animate={{ scaleX: 0 }}
403	                      transition={{ duration: 5, ease: "linear" }}
404	                      style={{ originX: 0 }}
405	                      className="absolute bottom-0 left-0 right-0 h-1 bg-white/40 z-0 pointer-events-none"
406	                    />
407	                  </button>
408	                </div>
409	              </motion.div>
410	            ) : (
411	              <motion.div
412	                key="pending"
413	                initial={{ opacity: 0, scale: 0.95 }}
414	                animate={{ opacity: 1, scale: 1 }}
415	                exit={{ opacity: 0, scale: 0.95 }}
416	                transition={{ type: "spring", stiffness: 350, damping: 25 }}
417	                className="space-y-5"
418	              >
419	                {/* Header */}
420	                <div className="flex items-center justify-between border-b border-white/[0.08] pb-4">
421	                  <div className="flex items-center space-x-3">
422	                    <div
423	                      className={`p-2.5 rounded-xl border ${
424	                        isMariBank
425	                          ? "bg-sky-500/10 border-sky-500/20 text-sky-400"
426	                          : "bg-blue-500/10 border-blue-500/20 text-blue-400"
427	                      }`}
428	                    >
429	                      {isMariBank ? <Building2 className="w-5 h-5" /> : <Smartphone className="w-5 h-5" />}
430	                    </div>
431	                    <div>
432	                      <div className="flex items-center space-x-2">
433	                        <h2 className="text-base font-bold text-white tracking-tight font-sans">
434	                          {channelDisplay} Automated P2P Top-Up
435	                        </h2>
436	                        <span className="px-2 py-0.5 rounded text-[10px] font-mono uppercase bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 font-semibold">
437	                          0% Fee
438	                        </span>
439	                      </div>
440	                      <p className="text-xs text-zinc-400 font-mono mt-0.5">
441	                        Session: <span className="text-zinc-300 font-bold">{sessionData?.sessionCode}</span>
442	                      </p>
443	                    </div>
444	                  </div>
445	
446	                  {/* Countdown Badge */}
447	                  <div
448	                    className={`flex items-center space-x-1.5 px-3 py-1 rounded-lg text-xs font-mono font-semibold border ${
449	                      timeLeft > 120
450	                        ? "bg-amber-500/10 text-amber-400 border-amber-500/20"
451	                        : timeLeft > 0
452	                        ? "bg-rose-500/15 text-rose-400 border-rose-500/30 animate-pulse"
453	                        : "bg-neutral-100 dark:bg-[#20232C] text-neutral-500 dark:text-zinc-400 border-neutral-200 dark:border-white/10"
454	                    }`}
455	                  >
456	                    <Clock className="w-3.5 h-3.5" />
457	                    <span>{timeLeft > 0 ? formattedCountdown : "Expired"}</span>
458	                  </div>
459	                </div>
460	
461	                {/* Dynamic QR Display & Centavos Match Pillar */}
462	                <div className="p-4 rounded-xl bg-neutral-50 dark:bg-[#14161D] border border-neutral-200 dark:border-white/10 space-y-4">
463	                  <div className="flex flex-col sm:flex-row items-center space-y-4 sm:space-y-0 sm:space-x-5">
464	                    {/* Dynamic QR Code (Click to Zoom) */}
465	                    {sessionData?.qrCodeUrl && (
466	                      <button
467	                        type="button"
468	                        onClick={() => setIsQrLightboxOpen(true)}
469	                        className="group relative w-36 h-36 p-2 bg-white rounded-xl shadow-md border border-neutral-200 dark:border-white/20 flex-shrink-0 flex items-center justify-center overflow-hidden cursor-zoom-in hover:ring-2 hover:ring-amber-400 transition-all focus:outline-none"
470	                        title="Click to enlarge QR code"
471	                        aria-label="Enlarge QR Code"
472	                      >
473	                        {/* eslint-disable-next-line @next/next/no-img-element */}
474	                        <img
475	                          src={sessionData.qrCodeUrl}
476	                          alt={`${channelDisplay} QR Code`}
477	                          className="w-full h-full object-contain rounded group-hover:scale-105 transition-transform"
478	                        />
479	                        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/25 transition-colors flex items-center justify-center">
480	                          <span className="opacity-0 group-hover:opacity-100 transition-opacity px-2 py-1 rounded bg-zinc-950/90 text-white text-[10px] font-mono flex items-center space-x-1 shadow-md">
481	                            <ZoomIn className="w-3 h-3 text-amber-400" />
482	                            <span>Zoom</span>
483	                          </span>
484	                        </div>
485	                      </button>
486	                    )}
487	
488	                    {/* Exact Centavos Amount Box */}
489	                    <div className="flex-1 space-y-3 font-mono text-xs w-full">
490	                      <div>
491	                        <div className="flex items-center justify-between text-[11px] text-zinc-400 uppercase tracking-wider mb-1">
492	                          <span>Send Exact Figure:</span>
493	                          <span className="text-amber-400 font-bold flex items-center gap-1">
494	                            <Sparkles className="w-3 h-3" />
495	                            <span>Match Key Active</span>
496	                          </span>
497	                        </div>
498	                        <div className="flex items-center justify-between p-2.5 rounded-lg bg-neutral-100 dark:bg-[#20232C] border border-neutral-200 dark:border-white/10">
499	                          <div>
500	                            <div className="text-2xl font-black text-emerald-400 tracking-tight">
501	                              ₱{sessionData ? Number(sessionData.expectedAmount).toFixed(2) : "0.00"}
502	                            </div>
503	                            <div className="text-[10px] text-zinc-400 mt-0.5">
504	                              Base: ₱{sessionData ? Number(sessionData.baseAmount).toFixed(2) : "0.00"} • Match Key:{" "}
505	                              <strong className="text-amber-300">
506	                                +₱{sessionData ? Number(sessionData.centavosOffset).toFixed(2) : "0.00"}
507	                              </strong>
508	                            </div>
509	                          </div>
510	
511	                          <button
512	                            type="button"
513	                            onClick={() =>
514	                              sessionData && copyText(Number(sessionData.expectedAmount).toFixed(2), "amount")
515	                            }
516	                            className="px-2.5 py-1.5 rounded-md bg-neutral-100 dark:bg-[#2A2E39] hover:bg-neutral-200 dark:hover:bg-[#343946] text-neutral-700 dark:text-zinc-200 text-xs font-mono flex items-center space-x-1.5 transition-colors border border-neutral-200 dark:border-white/10 cursor-pointer"
517	                            title="Copy Exact Amount"
518	                          >
519	                            {copiedAmount ? (
520	                              <>
521	                                <Check className="w-3.5 h-3.5 text-emerald-400" />
522	                                <span className="text-emerald-400 font-semibold">Copied</span>
523	                              </>
524	                            ) : (
525	                              <>
526	                                <Copy className="w-3.5 h-3.5 text-zinc-400" />
527	                                <span>Copy</span>
528	                              </>
529	                            )}
530	                          </button>
531	                        </div>
532	                      </div>
533	
534	                      <div className="flex items-center justify-between text-[11px] text-zinc-400 p-2 rounded-lg bg-zinc-950/80 border border-white/[0.08]">
535	                        <span>Account Name:</span>
536	                        <strong className="text-white">{sessionData?.receiverName || "XNIGHT COMMERCE"}</strong>
537	                      </div>
