"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  QrCode,
  Copy,
  Check,
  CheckCircle2,
  Clock,
  RefreshCw,
  AlertCircle,
  Smartphone,
  ShieldCheck,
  Building2,
  ZoomIn,
  X,
  Sparkles,
  Zap,
} from "lucide-react";
import { AnimatedModal } from "@/components/ui/modal";

export interface SettledDetails {
  amount: number;
  newBalance: number | null;
  paymentReference?: string | null;
  channel?: string | null;
}

export interface P2PTopupSessionData {
  sessionId: string;
  sessionCode: string;
  channel: "GCASH" | "MARIBANK" | "MAYA" | string;
  baseAmount: number;
  centavosOffset: number;
  expectedAmount: number;
  expiresAt?: string;
  qrCodeUrl: string;
  receiverName: string;
  receiverNumber: string;
  bankName?: string;
}

export interface P2PTopupModalProps {
  isOpen: boolean;
  onClose: () => void;
  sessionData: P2PTopupSessionData | null;
  onSuccess: () => void;
}

// Pleasant harmonic chime synthesizer for instant settlement celebration
function playP2PChime() {
  if (typeof window === "undefined") return;
  try {
    const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const now = ctx.currentTime;

    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = "sine";
    osc1.frequency.setValueAtTime(587.33, now); // D5
    osc1.frequency.exponentialRampToValueAtTime(880, now + 0.12); // A5
    gain1.gain.setValueAtTime(0.18, now);
    gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
    osc1.connect(gain1);
    gain1.connect(ctx.destination);
    osc1.start(now);
    osc1.stop(now + 0.35);

    const osc2 = ctx.createOscillator();
    const gain2 = ctx.createGain();
    osc2.type = "sine";
    osc2.frequency.setValueAtTime(1174.66, now + 0.14); // D6
    gain2.gain.setValueAtTime(0.2, now + 0.14);
    gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.7);
    osc2.connect(gain2);
    gain2.connect(ctx.destination);
    osc2.start(now + 0.14);
    osc2.stop(now + 0.7);
  } catch {
    // Graceful fallback if audio is not unlocked
  }
}

export function P2PTopupModal({
  isOpen,
  onClose,
  sessionData,
  onSuccess,
}: P2PTopupModalProps) {
  const [timeLeft, setTimeLeft] = useState<number>(15 * 60);
  const [copiedAmount, setCopiedAmount] = useState<boolean>(false);
  const [copiedAccount, setCopiedAccount] = useState<boolean>(false);
  const [isConfirmed, setIsConfirmed] = useState<boolean>(false);
  const [isQrLightboxOpen, setIsQrLightboxOpen] = useState<boolean>(false);
  const [settledDetails, setSettledDetails] = useState<SettledDetails | null>(null);
  const [autoCloseSeconds, setAutoCloseSeconds] = useState<number>(5);

  // Trigger confirmed settlement ceremony
  const handlePaymentSettled = useCallback(
    (details: SettledDetails) => {
      setSettledDetails(details);
      setIsConfirmed(true);
      playP2PChime();
      onSuccess();
    },
    [onSuccess]
  );

  // 5-Second Auto-Close Countdown upon Confirmed Settlement
  useEffect(() => {
    if (!isConfirmed) return;

    const timer = setInterval(() => {
      setAutoCloseSeconds((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          onClose();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [isConfirmed, onClose]);

  // Reset or initialize state when modal opens
  useEffect(() => {
    if (isOpen && sessionData) {
      setIsConfirmed(false);
      setSettledDetails(null);
      setAutoCloseSeconds(5);
      setCopiedAmount(false);
      setCopiedAccount(false);
      setIsQrLightboxOpen(false);

      let initialRemaining = 15 * 60;
      if (sessionData.expiresAt) {
        const expTime = new Date(sessionData.expiresAt).getTime();
        if (!isNaN(expTime)) {
          initialRemaining = Math.max(0, Math.floor((expTime - Date.now()) / 1000));
        }
      }
      setTimeLeft(initialRemaining);
    }
  }, [isOpen, sessionData]);

  // 15-Minute Countdown Timer
  useEffect(() => {
    if (!isOpen || !sessionData || isConfirmed || timeLeft <= 0) return;

    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [isOpen, sessionData, isConfirmed, timeLeft]);

  // Live session polling every 3 seconds
  useEffect(() => {
    const lookupId = sessionData?.sessionId || sessionData?.sessionCode;
    if (!isOpen || !lookupId || isConfirmed || timeLeft <= 0) return;

    let isMounted = true;

    async function pollSession() {
      if (!isMounted || isConfirmed || !lookupId) return;
      try {
        const res = await fetch(
          `/api/payment/p2p/status/${encodeURIComponent(lookupId)}?_t=${Date.now()}`,
          { cache: "no-store" }
        );
        if (!res.ok) return;
        const data = await res.json();
        if (!isMounted || isConfirmed) return;

        const isSettled =
          data?.status?.toUpperCase() === "COMPLETED" ||
          data?.status?.toUpperCase() === "SETTLED" ||
          Boolean(data?.isCompleted) ||
          Boolean(data?.isSettled) ||
          data?.session?.status?.toUpperCase() === "COMPLETED" ||
          data?.session?.status?.toUpperCase() === "SETTLED";

        if (isSettled) {
          const settledAmount =
            data.amount !== undefined && data.amount !== null
              ? Number(data.amount)
              : data.session?.received_amount !== undefined && data.session?.received_amount !== null
              ? Number(data.session.received_amount)
              : Number(sessionData?.expectedAmount ?? 0);

          const settledNewBalance =
            data.newBalance !== undefined && data.newBalance !== null
              ? Number(data.newBalance)
              : data.session?.newBalance !== undefined && data.session?.newBalance !== null
              ? Number(data.session.newBalance)
              : null;

          const settledRef =
            data.paymentReference ||
            data.payment_reference ||
            data.session?.payment_reference ||
            null;

          const settledChan =
            data.channel ||
            data.session?.channel ||
            sessionData?.channel ||
            "P2P";

          handlePaymentSettled({
            amount: settledAmount,
            newBalance: settledNewBalance,
            paymentReference: settledRef,
            channel: settledChan,
          });
        }
      } catch {
        // Continue polling silently
      }
    }

    const pollInterval = setInterval(pollSession, 3000);
    // Trigger initial poll immediately
    pollSession();

    return () => {
      isMounted = false;
      clearInterval(pollInterval);
    };
  }, [
    isOpen,
    sessionData?.sessionId,
    sessionData?.sessionCode,
    sessionData?.expectedAmount,
    sessionData?.channel,
    isConfirmed,
    timeLeft,
    handlePaymentSettled,
  ]);

  const copyText = (text: string, type: "amount" | "account") => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    if (type === "amount") {
      setCopiedAmount(true);
      setTimeout(() => setCopiedAmount(false), 2000);
    } else {
      setCopiedAccount(true);
      setTimeout(() => setCopiedAccount(false), 2000);
    }
  };

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const formattedCountdown = `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;

  const isMariBank = String(sessionData?.channel || "").toUpperCase().includes("MARI");
  const channelDisplay = isMariBank ? "MariBank" : "GCash";
  const creditedAmount =
    settledDetails?.amount !== undefined
      ? settledDetails.amount
      : sessionData
      ? Number(sessionData.expectedAmount)
      : 0;
  const settledNewBalance = settledDetails?.newBalance;
  const displayChannel =
    settledDetails?.channel || channelDisplay;
  const displayReference =
    settledDetails?.paymentReference || null;

  return (
    <>
      <AnimatedModal
        isOpen={isOpen && !!sessionData}
        onClose={onClose}
        maxWidth="max-w-lg"
        className="border border-neutral-200 dark:border-white/10 shadow-2xl rounded-2xl bg-white dark:bg-[#14161D] text-neutral-900 dark:text-zinc-100 overflow-hidden"
      >
        <div className="p-6">
          <AnimatePresence mode="wait">
            {isConfirmed ? (
              <motion.div
                key="confirmed"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ type: "spring", stiffness: 350, damping: 25 }}
                className="space-y-5"
              >
                {/* Double-Bezel Rounded Card */}
                <div className="rounded-2xl p-[1px] bg-gradient-to-b from-emerald-500/30 via-white/[0.08] to-white/[0.02] shadow-2xl shadow-emerald-950/20">
                  <div className="rounded-[15px] bg-neutral-50 dark:bg-[#14161D] border border-neutral-200 dark:border-white/10 p-6 space-y-6 relative overflow-hidden">
                    {/* Emerald Radial Background Glow */}
                    <div className="absolute -top-24 left-1/2 -translate-x-1/2 w-64 h-48 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none" />

                    {/* Animated Emerald Glowing Badge with Checkmark */}
                    <div className="relative mx-auto w-16 h-16 flex items-center justify-center">
                      <div className="absolute inset-0 rounded-full bg-emerald-400/20 blur-xl animate-pulse" />
                      <div className="relative w-14 h-14 rounded-full bg-emerald-500/15 border border-emerald-400/30 ring-1 ring-emerald-400/20 flex items-center justify-center shadow-lg shadow-emerald-500/20">
                        <motion.div
                          initial={{ scale: 0.8, opacity: 0 }}
                          animate={{ scale: 1, opacity: 1 }}
                          transition={{ type: "spring", stiffness: 400, damping: 20, delay: 0.08 }}
                        >
                          <CheckCircle2 className="w-8 h-8 text-emerald-400" />
                        </motion.div>
                      </div>
                    </div>

                    {/* Headline */}
                    <div className="text-center space-y-1">
                      <h3 className="text-xl font-bold text-white tracking-tight font-sans">
                        Top-Up Confirmed
                      </h3>
                      <p className="text-xs text-zinc-400 font-sans">
                        Funds verified &amp; instantly credited to your wholesale float
                      </p>
                    </div>

                    {/* Monospace Currency Chip (JetBrains Mono): "+₱1.47 Credited" */}
                    <div className="flex justify-center">
                      <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-emerald-500/10 border border-emerald-500/25 text-emerald-300 font-mono tabular-nums text-sm font-bold shadow-sm">
                        <Sparkles className="w-4 h-4 text-emerald-400 shrink-0" />
                        <span>+₱{creditedAmount.toFixed(2)} Credited</span>
                      </div>
                    </div>

                    {/* New Usable Balance Display: "Updated Float: ₱1,055.86" */}
                    <div className="p-4 rounded-xl bg-zinc-950/80 border border-white/[0.06] text-center space-y-1">
                      <div className="text-[11px] font-sans font-medium text-zinc-400 uppercase tracking-wider">
                        Usable Wholesale Float
                      </div>
                      <div className="text-2xl font-bold font-mono tabular-nums text-white tracking-tight">
                        {settledNewBalance !== null && settledNewBalance !== undefined
                          ? `Updated Float: ₱${settledNewBalance.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
                          : `Updated Float: ₱${creditedAmount.toFixed(2)}`}
                      </div>
                      <div className="text-[11px] font-mono text-emerald-400 flex items-center justify-center space-x-1">
                        <Check className="w-3.5 h-3.5" />
                        <span>Available for automated order fulfillment upon confirmation</span>
                      </div>
                    </div>

                    {/* Transaction Reference & Bank Channel Indicator */}
                    <div className="space-y-2 pt-1 font-mono text-xs">
                      <div className="flex items-center justify-between p-2.5 rounded-lg bg-zinc-950/60 border border-white/[0.04]">
                        <span className="text-zinc-400 text-[11px]">Bank Channel:</span>
                        <div className="flex items-center space-x-1.5 text-zinc-200 font-semibold">
                          {displayChannel.toUpperCase().includes("MARI") ? (
                            <Building2 className="w-3.5 h-3.5 text-sky-400" />
                          ) : (
                            <Smartphone className="w-3.5 h-3.5 text-blue-400" />
                          )}
                          <span>{displayChannel}</span>
                        </div>
                      </div>

                      <div className="flex items-center justify-between p-2.5 rounded-lg bg-zinc-950/60 border border-white/[0.04]">
                        <span className="text-zinc-400 text-[11px]">Session Code:</span>
                        <span className="text-zinc-200 font-semibold font-mono">{sessionData?.sessionCode}</span>
                      </div>

                      {displayReference && (
                        <div className="flex items-center justify-between p-2.5 rounded-lg bg-zinc-950/60 border border-white/[0.04]">
                          <span className="text-zinc-400 text-[11px]">Bank Ref:</span>
                          <span className="text-emerald-400 font-mono text-[11px] truncate max-w-[200px]" title={displayReference}>
                            {displayReference}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                {/* Primary Action Button: "Done / Back to Wallet" (with 5-second auto-close progress bar) */}
                <div className="pt-1">
                  <button
                    type="button"
                    onClick={onClose}
                    className="group relative w-full overflow-hidden py-3 px-4 rounded-xl bg-gradient-to-r from-emerald-600 to-emerald-500 hover:from-emerald-500 hover:to-emerald-400 text-white font-sans font-semibold text-xs uppercase tracking-wider transition-all shadow-lg shadow-emerald-950/40 active:scale-[0.98] duration-150"
                  >
                    <span className="relative z-10 flex items-center justify-center space-x-2">
                      <span>Done / Back to Wallet</span>
                      <span className="text-emerald-100/90 font-mono text-xs tabular-nums lowercase">
                        ({autoCloseSeconds}s)
                      </span>
                    </span>
                    {/* 5-second auto-close progress bar */}
                    <motion.div
                      initial={{ scaleX: 1 }}
                      animate={{ scaleX: 0 }}
                      transition={{ duration: 5, ease: "linear" }}
                      style={{ originX: 0 }}
                      className="absolute bottom-0 left-0 right-0 h-1 bg-white/40 z-0 pointer-events-none"
                    />
                  </button>
                </div>
              </motion.div>
            ) : (
              <motion.div
                key="pending"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ type: "spring", stiffness: 350, damping: 25 }}
                className="space-y-5"
              >
                {/* Header */}
                <div className="flex items-center justify-between border-b border-white/[0.08] pb-4">
                  <div className="flex items-center space-x-3">
                    <div
                      className={`p-2.5 rounded-xl border ${
                        isMariBank
                          ? "bg-sky-500/10 border-sky-500/20 text-sky-400"
                          : "bg-blue-500/10 border-blue-500/20 text-blue-400"
                      }`}
                    >
                      {isMariBank ? <Building2 className="w-5 h-5" /> : <Smartphone className="w-5 h-5" />}
                    </div>
                    <div>
                      <div className="flex items-center space-x-2">
                        <h2 className="text-base font-bold text-white tracking-tight font-sans">
                          {channelDisplay} Automated P2P Top-Up
                        </h2>
                        <span className="px-2 py-0.5 rounded text-[10px] font-mono uppercase bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 font-semibold">
                          0% Fee
                        </span>
                      </div>
                      <p className="text-xs text-zinc-400 font-mono mt-0.5">
                        Session: <span className="text-zinc-300 font-bold">{sessionData?.sessionCode}</span>
                      </p>
                    </div>
                  </div>

                  {/* Countdown Badge */}
                  <div
                    className={`flex items-center space-x-1.5 px-3 py-1 rounded-lg text-xs font-mono font-semibold border ${
                      timeLeft > 120
                        ? "bg-amber-500/10 text-amber-400 border-amber-500/20"
                        : timeLeft > 0
                        ? "bg-rose-500/15 text-rose-400 border-rose-500/30 animate-pulse"
                        : "bg-neutral-100 dark:bg-[#20232C] text-neutral-500 dark:text-zinc-400 border-neutral-200 dark:border-white/10"
                    }`}
                  >
                    <Clock className="w-3.5 h-3.5" />
                    <span>{timeLeft > 0 ? formattedCountdown : "Expired"}</span>
                  </div>
                </div>

                {/* Dynamic QR Display & Centavos Match Pillar */}
                <div className="p-4 rounded-xl bg-neutral-50 dark:bg-[#14161D] border border-neutral-200 dark:border-white/10 space-y-4">
                  <div className="flex flex-col sm:flex-row items-center space-y-4 sm:space-y-0 sm:space-x-5">
                    {/* Dynamic QR Code (Click to Zoom) */}
                    {sessionData?.qrCodeUrl && (
                      <button
                        type="button"
                        onClick={() => setIsQrLightboxOpen(true)}
                        className="group relative w-36 h-36 p-2 bg-white rounded-xl shadow-md border border-neutral-200 dark:border-white/20 flex-shrink-0 flex items-center justify-center overflow-hidden cursor-zoom-in hover:ring-2 hover:ring-amber-400 transition-all focus:outline-none"
                        title="Click to enlarge QR code"
                        aria-label="Enlarge QR Code"
                      >
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img
                          src={sessionData.qrCodeUrl}
                          alt={`${channelDisplay} QR Code`}
                          className="w-full h-full object-contain rounded group-hover:scale-105 transition-transform"
                        />
                        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/25 transition-colors flex items-center justify-center">
                          <span className="opacity-0 group-hover:opacity-100 transition-opacity px-2 py-1 rounded bg-zinc-950/90 text-white text-[10px] font-mono flex items-center space-x-1 shadow-md">
                            <ZoomIn className="w-3 h-3 text-amber-400" />
                            <span>Zoom</span>
                          </span>
                        </div>
                      </button>
                    )}

                    {/* Exact Centavos Amount Box */}
                    <div className="flex-1 space-y-3 font-mono text-xs w-full">
                      <div>
                        <div className="flex items-center justify-between text-[11px] text-zinc-400 uppercase tracking-wider mb-1">
                          <span>Send Exact Figure:</span>
                          <span className="text-amber-400 font-bold flex items-center gap-1">
                            <Sparkles className="w-3 h-3" />
                            <span>Match Key Active</span>
                          </span>
                        </div>
                        <div className="flex items-center justify-between p-2.5 rounded-lg bg-neutral-100 dark:bg-[#20232C] border border-neutral-200 dark:border-white/10">
                          <div>
                            <div className="text-2xl font-black text-emerald-400 tracking-tight">
                              ₱{sessionData ? Number(sessionData.expectedAmount).toFixed(2) : "0.00"}
                            </div>
                            <div className="text-[10px] text-zinc-400 mt-0.5">
                              Base: ₱{sessionData ? Number(sessionData.baseAmount).toFixed(2) : "0.00"} • Match Key:{" "}
                              <strong className="text-amber-300">
                                +₱{sessionData ? Number(sessionData.centavosOffset).toFixed(2) : "0.00"}
                              </strong>
                            </div>
                          </div>

                          <button
                            type="button"
                            onClick={() =>
                              sessionData && copyText(Number(sessionData.expectedAmount).toFixed(2), "amount")
                            }
                            className="px-2.5 py-1.5 rounded-md bg-neutral-100 dark:bg-[#2A2E39] hover:bg-neutral-200 dark:hover:bg-[#343946] text-neutral-700 dark:text-zinc-200 text-xs font-mono flex items-center space-x-1.5 transition-colors border border-neutral-200 dark:border-white/10 cursor-pointer"
                            title="Copy Exact Amount"
                          >
                            {copiedAmount ? (
                              <>
                                <Check className="w-3.5 h-3.5 text-emerald-400" />
                                <span className="text-emerald-400 font-semibold">Copied</span>
                              </>
                            ) : (
                              <>
                                <Copy className="w-3.5 h-3.5 text-zinc-400" />
                                <span>Copy</span>
                              </>
                            )}
                          </button>
                        </div>
                      </div>

                      <div className="flex items-center justify-between text-[11px] text-zinc-400 p-2 rounded-lg bg-zinc-950/80 border border-white/[0.08]">
                        <span>Account Name:</span>
                        <strong className="text-white">{sessionData?.receiverName || "XNIGHT COMMERCE"}</strong>
                      </div>
                    </div>
                  </div>

                  {/* Important Centavos Warning */}
                  <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/20 text-amber-300 text-[11px] font-mono leading-relaxed space-y-1">
                    <div className="font-bold flex items-center space-x-1.5">
                      <AlertCircle className="w-3.5 h-3.5 text-amber-400 shrink-0" />
                      <span>Scan via QR &amp; Pay Exact Centavos</span>
                    </div>
                    <p className="text-zinc-300">
                      Do NOT round off. The unique centavos amount (
                      <strong className="text-amber-300 font-bold">
                        ₱{sessionData ? Number(sessionData.expectedAmount).toFixed(2) : "0.00"}
                      </strong>
                      ) is verified instantly by the MacroDroid automated listener without manual human delay.
                    </p>
                  </div>
                </div>

                {/* Live Polling Spinner */}
                <div className="p-3 rounded-xl bg-neutral-100 dark:bg-[#20232C] border border-neutral-200 dark:border-white/10 flex items-center justify-between text-xs font-mono">
                  <div className="flex items-center space-x-2.5">
                    <div className="relative flex items-center justify-center">
                      <span className="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-ping absolute" />
                      <span className="w-2 h-2 rounded-full bg-emerald-400" />
                    </div>
                    <span className="text-neutral-700 dark:text-zinc-300">Waiting for {channelDisplay} push confirmation...</span>
                  </div>
                  <div className="flex items-center space-x-1 text-zinc-500 text-[11px]">
                    <RefreshCw className="w-3 h-3 animate-spin" />
                    <span>Polling 3s</span>
                  </div>
                </div>

                {/* Modal Footer Actions */}
                <div className="flex space-x-3 pt-2">
                  <button
                    type="button"
                    onClick={onClose}
                    className="flex-1 py-2.5 px-4 rounded-xl bg-neutral-100 dark:bg-[#20232C] hover:bg-neutral-200 dark:hover:bg-[#2A2E39] text-neutral-800 dark:text-zinc-200 border border-neutral-200 dark:border-white/10 text-xs font-mono font-semibold uppercase tracking-wider transition-colors active:scale-[0.98] cursor-pointer"
                  >
                    Cancel / Close
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </AnimatedModal>

      {/* Fullscreen Click-to-Zoom Lightbox for QR code */}
      {isQrLightboxOpen && sessionData?.qrCodeUrl && (
        <div
          className="fixed inset-0 z-[70] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-in fade-in duration-200"
          onClick={() => setIsQrLightboxOpen(false)}
          role="dialog"
          aria-modal="true"
        >
          <div
            className="relative w-full max-w-sm rounded-2xl bg-white dark:bg-[#14161D] border border-neutral-200 dark:border-white/10 p-6 shadow-2xl flex flex-col items-center space-y-4"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between w-full border-b border-neutral-200 dark:border-white/10 pb-3">
              <span className="text-xs font-mono font-bold text-neutral-900 dark:text-white">
                {channelDisplay} Official Dynamic QR
              </span>
              <button
                type="button"
                onClick={() => setIsQrLightboxOpen(false)}
                className="text-zinc-400 hover:text-white"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="bg-white p-3 rounded-xl border border-neutral-200 dark:border-white/10">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={sessionData.qrCodeUrl}
                alt="Enlarged QR Code"
                className="w-64 h-64 object-contain rounded"
              />
            </div>

            <div className="w-full text-center font-mono">
              <div className="text-[11px] text-zinc-400 uppercase">Exact Amount to Pay:</div>
              <div className="text-xl font-bold text-emerald-400 mt-0.5">
                ₱{Number(sessionData.expectedAmount).toFixed(2)} PHP
              </div>
            </div>

            <button
              type="button"
              onClick={() => setIsQrLightboxOpen(false)}
              className="w-full py-2 rounded-xl bg-neutral-100 dark:bg-[#20232C] hover:bg-neutral-200 dark:hover:bg-[#2A2E39] text-neutral-800 dark:text-zinc-200 border border-neutral-200 dark:border-white/10 text-xs font-mono font-semibold uppercase tracking-wider cursor-pointer"
            >
              Close Zoom [ ✕ ]
            </button>
          </div>
        </div>
      )}
    </>
  );
}

