// app/api/payment/p2p/create/route.ts — Create P2P Payment Session with Allocated Centavos Match Key

import { NextRequest, NextResponse } from "next/server";
import { requireRole, verifyOrderAccess } from "@/app/lib/auth";
import { CentavosAllocatorService } from "@/src/services/centavos-allocator.service";
import { SettingsService } from "@/src/services/settings.service";
import { P2PPaymentChannel, P2PTargetType } from "@/src/types/p2p-payment";
import { checkRateLimit } from "@/src/services/rate-limiter.service";
import { getClientIp } from "@/app/lib/ip";

export async function POST(request: NextRequest) {
  try {
    const ip = getClientIp(request);
    const rateLimit = await checkRateLimit("p2p:create:" + ip, { windowMs: 60_000, maxRequests: 5 });
    if (!rateLimit.allowed) {
      return NextResponse.json(
        { success: false, error: "RATE_LIMITED", message: "Too many payment creation requests. Please try again shortly." },
        { status: 429 }
      );
    }

    let body: any = {};
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { success: false, error: "INVALID_JSON", message: "Invalid JSON request body" },
        { status: 400 }
      );
    }

    // Normalize payment channel (GCASH, MARIBANK, or MAYA)
    const channelInput = String(body.channel || "GCASH").trim().toUpperCase();
    let channel: P2PPaymentChannel = "GCASH";
    if (channelInput.includes("MARI") || channelInput.includes("SEA")) {
      channel = "MARIBANK";
    } else if (channelInput.includes("MAYA")) {
      channel = "MAYA";
    } else {
      channel = "GCASH";
    }

    const sessionType = String(body.session_type || body.sessionType || "WALLET_TOPUP").toUpperCase();
    let targetType: P2PTargetType = "RESELLER_TOPUP";
    let targetReferenceId = body.targetReferenceId || "";
    let baseAmount = 0;
    let payerIdentity: string | undefined = undefined;
    let payerOwnershipType: "GUEST" | "CUSTOMER" | "RESELLER" | undefined = undefined;

    if (sessionType === "WALLET_TOPUP" || sessionType === "RESELLER_TOPUP") {
      targetType = "RESELLER_TOPUP";
      const rawAmount = Number(body.amount);
      if (!Number.isFinite(rawAmount) || isNaN(rawAmount) || rawAmount <= 0) {
        return NextResponse.json(
          { success: false, error: "INVALID_AMOUNT", message: "Amount must be a positive number" },
          { status: 400 }
        );
      }

      if (rawAmount < 1) {
        return NextResponse.json(
          { success: false, error: "MINIMUM_AMOUNT_UNMET", message: "Minimum top-up amount is ₱1.00" },
          { status: 400 }
        );
      }
      baseAmount = rawAmount;

      // Authenticate reseller session
      const auth = await requireRole(request, ["reseller"]);
      if (auth.errorResponse) {
        return auth.errorResponse;
      }
      targetReferenceId = auth.context?.organization?.id || auth.context?.user?.id || "";
      if (!targetReferenceId) {
        return NextResponse.json(
          { success: false, error: "UNAUTHORIZED_RESELLER", message: "Valid reseller profile required" },
          { status: 401 }
        );
      }
      payerIdentity = auth.context?.organization?.id || auth.context?.user?.id;
      payerOwnershipType = "RESELLER";
    } else if (sessionType === "STOREFRONT_ORDER") {
      targetType = "STOREFRONT_ORDER";
      targetReferenceId = String(body.orderCode || body.orderId || body.targetReferenceId || "").trim();
      if (!targetReferenceId) {
        return NextResponse.json(
          { success: false, error: "MISSING_ORDER_CODE", message: "Order code required for storefront checkout" },
          { status: 400 }
        );
      }

      // Verify order access (customer ownership or valid guest capability token)
      const orderAuth = await verifyOrderAccess(request, targetReferenceId, {
        allowGuest: true,
        token: body.token || body.guestToken || body.guest_token,
      });
      if (!orderAuth.authorized || !orderAuth.order) {
        return orderAuth.errorResponse!;
      }
      const order = orderAuth.order;
      const custId = order.customer_id;
      payerIdentity = custId ? String(custId) : (order.code || targetReferenceId);
      payerOwnershipType = custId ? "CUSTOMER" : "GUEST";

      // Validate payable state
      const orderState = String(order.state || order.status || "").toUpperCase();
      const nonPayableStates = ["PAID", "PROCESSING", "DELIVERED", "COMPLETED", "FULFILLED", "CANCELLED", "REJECTED"];
      if (nonPayableStates.includes(orderState)) {
        return NextResponse.json(
          {
            success: false,
            error: "ORDER_NOT_PAYABLE",
            message: `Order #${order.code || targetReferenceId} is in state '${orderState}' and cannot accept payment.`,
          },
          { status: 400 }
        );
      }

      // Authoritative DB total derived from immutable snapshot base
      const unitPrice = Number(order.unit_price_snapshot || order.variant_snapshot?.price || order.total);
      const canonicalBase = Math.round(unitPrice * Number(order.quantity || 1) * 100) / 100;
      if (!Number.isFinite(canonicalBase) || canonicalBase <= 0) {
        return NextResponse.json(
          { success: false, error: "INVALID_ORDER_TOTAL", message: "Order total is invalid." },
          { status: 400 }
        );
      }

      // Reject tampered client amount if provided
      if (body.amount !== undefined && body.amount !== null) {
        const clientAmount = Number(body.amount);
        if (Math.abs(clientAmount - canonicalBase) > 0.01) {
          return NextResponse.json(
            {
              success: false,
              error: "AMOUNT_MISMATCH",
              message: `Client provided amount (${clientAmount}) does not match authoritative order base (${canonicalBase}).`,
            },
            { status: 400 }
          );
        }
      }

      baseAmount = canonicalBase;
      targetReferenceId = String(order.id);
    } else {
      return NextResponse.json(
        { success: false, error: "INVALID_SESSION_TYPE", message: `Unknown session type '${sessionType}'` },
        { status: 400 }
      );
    }

    // Retrieve active payment receiver accounts & QR codes
    const receiverConfig = await SettingsService.getPaymentReceiverConfig().catch(() => null);

    // Enforce channel availability: reject disabled methods with HTTP 400 PAYMENT_METHOD_DISABLED
    if (receiverConfig) {
      if (channel === "MARIBANK" && receiverConfig.maribankEnabled === false) {
        return NextResponse.json(
          {
            success: false,
            error: "PAYMENT_METHOD_DISABLED",
            message: "MariBank QR payment method is currently disabled.",
          },
          { status: 400 }
        );
      }
      if (channel === "GCASH" && receiverConfig.gcashEnabled === false) {
        return NextResponse.json(
          {
            success: false,
            error: "PAYMENT_METHOD_DISABLED",
            message: "GCash payment method is currently disabled.",
          },
          { status: 400 }
        );
      }
      if (channel === "MAYA" && receiverConfig.mayaEnabled === false) {
        return NextResponse.json(
          {
            success: false,
            error: "PAYMENT_METHOD_DISABLED",
            message: "Maya payment method is currently disabled.",
          },
          { status: 400 }
        );
      }
    }

    let qrCodeUrl = "";
    let receiverName = "XEURIE COMMERCE";
    let receiverNumber = "";
    let bankName = "";

    if (channel === "GCASH") {
      qrCodeUrl = receiverConfig?.gcashQrUrl || "/payment/gcash.jpg";
      receiverName = receiverConfig?.gcashName || "XEURIE COMMERCE";
      receiverNumber = receiverConfig?.gcashNumber || "";
    } else if (channel === "MARIBANK") {
      qrCodeUrl = receiverConfig?.maribankQrUrl || "/payment/maribank.jpg";
      receiverName = receiverConfig?.maribankName || "XEURIE COMMERCE";
      receiverNumber = receiverConfig?.maribankNumber || "";
      bankName = receiverConfig?.bankName || "MariBank / SeaBank";
    } else if (channel === "MAYA") {
      qrCodeUrl = receiverConfig?.mayaQrUrl || "";
      receiverName = receiverConfig?.mayaName || "XEURIE COMMERCE";
      receiverNumber = receiverConfig?.mayaNumber || "";
    }

    // Allocate collision-free centavos & create 15-minute lease session
    const { session, error } = await CentavosAllocatorService.createSession({
      targetType,
      targetReferenceId,
      channel,
      baseAmount,
      currency: "PHP",
      receivingAccount: receiverNumber || undefined,
      payerIdentity,
      payerOwnershipType,
      idempotencyKey: body.idempotencyKey || (targetType === "STOREFRONT_ORDER" ? `order_${targetReferenceId}_${channel}` : undefined),
      metadata: {
        ...(body.metadata || {}),
        session_type: sessionType,
        source: "p2p_automated_engine",
      },
      leaseMinutes: 15,
    });

    if (!session || error) {
      const isListenerOffline = error === "LISTENER_OFFLINE";
      const isSaturated = error === "SLOTS_SATURATED";
      return NextResponse.json(
        {
          success: false,
          error: error || "SESSION_CREATION_FAILED",
          message: isListenerOffline
            ? "Automated P2P payment listener is currently offline. Please try another payment method or contact support."
            : isSaturated
            ? "All centavos collision slots are currently saturated for this channel. Please try again in a few moments."
            : error || "Failed to create P2P payment session.",
        },
        { status: isListenerOffline ? 503 : isSaturated ? 429 : 400 }
      );
    }

    return NextResponse.json(
      {
        success: true,
        sessionId: session.id,
        sessionCode: session.session_code,
        channel: session.channel,
        baseAmount: session.base_amount,
        centavosOffset: session.centavos_offset,
        expectedAmount: session.expected_amount,
        fee: 0,
        totalPayable: session.expected_amount,
        expiresAt: session.expires_at,
        status: session.status,
        qrCodeUrl,
        receiverName,
        receiverNumber,
        bankName,
        session: {
          id: session.id,
          session_code: session.session_code,
          channel: session.channel,
          base_amount: session.base_amount,
          centavos_offset: session.centavos_offset,
          expected_amount: session.expected_amount,
          status: session.status,
          expires_at: session.expires_at,
          qr_code_url: qrCodeUrl,
          receiver_name: receiverName,
          receiver_number: receiverNumber,
          bank_name: bankName,
        },
      },
      { status: 201 }
    );
  } catch (err: any) {
    return NextResponse.json(
      { success: false, error: "INTERNAL_ERROR", message: err?.message || "Failed to process P2P payment request." },
      { status: 500 }
    );
  }
}

