const parsedQrAmount = Math.max(0, parseFloat(qrAmount) || 0);

const executeGenerateP2PQr = async () => {
  setError(null);
  setQrLoading(true);

  try {
    // Pre-flight MacroDroid heartbeat check
    try {
      const hbRes = await fetch("/api/payment/listener/heartbeat");
      if (hbRes.ok) {
        const hbData = await hbRes.json();
        if (hbData?.p2pActive !== undefined) {
          setListenerOnline(hbData.p2pActive);
        }
      }
    } catch {}

    const channelValue = p2pChannel === "MariBank" ? "p2p_maribank" : "p2p_gcash";

    const res = await fetch("/api/payment/p2p/create", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        amount: parsedQrAmount,
        channel: channelValue,
        session_type: "WALLET_TOPUP",
      }),
    });

    const data = await res.json();
    if (!res.ok || !data.success) {
      throw new Error(data.message || data.error || "Failed to initialize P2P payment session");
    }

    const newSession: P2PTopupSessionData = {
      sessionId: data.sessionId || data.session?.id,
      sessionCode: data.sessionCode || data.session?.session_code,
      channel: data.channel || data.session?.channel || p2pChannel,
      baseAmount: data.baseAmount ?? data.session?.base_amount ?? parsedQrAmount,
      centavosOffset: data.centavosOffset ?? data.session?.centavos_offset ?? 0,
      expectedAmount: data.expectedAmount ?? data.session?.expected_amount ?? parsedQrAmount,
      expiresAt: data.expiresAt || data.session?.expires_at,
      qrCodeUrl: data.qrCodeUrl || data.session?.qr_code_url,
      receiverName: data.receiverName || data.session?.receiver_name || "XNIGHT COMMERCE",
      receiverNumber: "",
      bankName: data.bankName || data.session?.bank_name,
    };

    updateSessionData(newSession);

    let initialRemaining = 15 * 60;
    if (newSession.expiresAt) {
      const expTime = new Date(newSession.expiresAt).getTime();
      if (!isNaN(expTime)) {
        initialRemaining = Math.max(0, Math.floor((expTime - Date.now()) / 1000));
      }
    }
    setSessionTimeLeft(initialRemaining);
    setIsSessionSettled(false);
    setSessionSettledDetails(null);

    // Automatically switch to Payment Status tab so the user sees the active timer & poller
    setActiveTab("status");
  } catch (err: any) {
    setError(err.message || "Failed to generate dynamic P2P QR Ph code");
  } finally {
    setQrLoading(false);
  }
};

const handleGenerateQr = async () => {
  if (parsedQrAmount < 1) {
    setError("Minimum QR Ph top-up amount is ₱1.00");
    return;
  }
  const warningDismissed = isP2PWarningDismissed();
  if (!warningDismissed) {
    setIsP2PWarningOpen(true);
    return;
  }
  await executeGenerateP2PQr();
};

const copyToClipboard = (text: string, key: string) => {
